// --- 2. HELPER FUNCTIONS ---
float relu(float x) { return (x > 0) ? x : 0; }

// --- 3. PREDICTION FUNCTION ---
// Pass the 64 sensor readings array here.
// Returns: 0=Aspirin, 1=Fake, 2=Paracetamol, 3=Vitamin_C
int predict_drug(float* sensor_data) {
    
    // A. Feature Engineering (Max Amp)
    float max_amp = 0;
    for(int i=0; i<64; i++) {
        if(sensor_data[i] > max_amp) max_amp = sensor_data[i];
    }

    // B. Normalize Inputs (65 Features)
    float input[65];
    for(int i=0; i<64; i++) {
        input[i] = (sensor_data[i] - SCALER_MEAN[i]) / SCALER_SCALE[i];
    }
    input[64] = (max_amp - SCALER_MEAN[64]) / SCALER_SCALE[64];

    // C. Layer 1 (65 -> 16)
    float l1[16];
    for(int i=0; i<16; i++) {
        l1[i] = BIAS_1[i];
        for(int j=0; j<65; j++) {
            l1[i] += input[j] * WEIGHTS_1[j * 16 + i];
        }
        l1[i] = relu(l1[i]);
    }

    // D. Layer 2 (16 -> 8)
    float l2[8];
    for(int i=0; i<8; i++) {
        l2[i] = BIAS_2[i];
        for(int j=0; j<16; j++) {
            l2[i] += l1[j] * WEIGHTS_2[j * 8 + i];
        }
        l2[i] = relu(l2[i]);
    }

    // E. Output Layer (8 -> 4)
    float output[4];
    int max_index = -1;
    float max_val = -99999.0;
    
    for(int i=0; i<4; i++) {
        output[i] = BIAS_3[i];
        for(int j=0; j<8; j++) {
            output[i] += l2[j] * WEIGHTS_3[j * 4 + i];
        }
        if(output[i] > max_val) {
            max_val = output[i];
            max_index = i;
        }
    }
    
    return max_index;
}
